const sleepData = $input.first().json.data;

if (!sleepData || sleepData.length === 0) {
  return [{ json: { error: 'No sleep data found', skip: true } }];
}

// recommended sleep per night in seconds (8 hours)
const RECOMMENDED_SLEEP_SECONDS = 8 * 3600;

let totalDebt = 0;
let dailyBreakdown = [];
let worstNight = null;
let bestNight = null;

for (const night of sleepData) {
  const totalSleep = night.total_sleep_duration || 0;
  const efficiency = night.efficiency || 0;
  const remSleep = night.rem_sleep_duration || 0;
  const deepSleep = night.deep_sleep_duration || 0;
  const date = night.day;

  const deficit = RECOMMENDED_SLEEP_SECONDS - totalSleep;
  totalDebt += deficit > 0 ? deficit : 0;

  const entry = {
    date,
    totalSleepHours: (totalSleep / 3600).toFixed(2),
    efficiency,
    remHours: (remSleep / 3600).toFixed(2),
    deepHours: (deepSleep / 3600).toFixed(2),
    deficitHours: (deficit / 3600).toFixed(2),
    score: night.score || null
  };

  dailyBreakdown.push(entry);

  if (!worstNight || totalSleep < worstNight.totalSleep) {
    worstNight = { ...entry, totalSleep };
  }
  if (!bestNight || totalSleep > bestNight.totalSleep) {
    bestNight = { ...entry, totalSleep };
  }
}

const avgSleepHours = dailyBreakdown.reduce((s, d) => s + parseFloat(d.totalSleepHours), 0) / dailyBreakdown.length;
const totalDebtHours = (totalDebt / 3600).toFixed(1);

return [{
  json: {
    summary: {
      totalDebtHours,
      avgSleepHours: avgSleepHours.toFixed(2),
      daysAnalyzed: dailyBreakdown.length,
      worstNight,
      bestNight
    },
    dailyBreakdown,
    analysisDate: $now.toISO()
  }
}];

const coaching = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const sleepNode = $('Calculate Sleep Debt').first().json;

const debtHours = parseFloat(sleepNode.summary.totalDebtHours);
let urgencyEmoji = '🟢';
if (debtHours > 10) urgencyEmoji = '🔴';
else if (debtHours > 5) urgencyEmoji = '🟡';

const subject = `${urgencyEmoji} Your Sleep Report — ${debtHours}h debt this week`;

const htmlBody = `
