    .subtitle { color: #777; font-size: 14px; }
    .stat-row { display: flex; gap: 16px; margin: 20px 0; }
    .stat { background: #fff; border: 1px solid #e5e0d8; border-radius: 8px; padding: 14px 18px; flex: 1; }
    .stat-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; color: #999; }
    .stat-value { font-size: 26px; font-weight: bold; color: #2c2c2c; margin-top: 4px; }
    .coaching { background: #fff; border-left: 3px solid #c9a96e; padding: 20px 24px; border-radius: 0 8px 8px 0; line-height: 1.7; font-size: 15px; white-space: pre-wrap; }
    .footer { margin-top: 28px; font-size: 12px; color: #aaa; border-top: 1px solid #eee; padding-top: 12px; }
  </style>
